'use client'

import React from 'react'

/**
 * Kepenk Editor — SVG Icon Library
 * ─────────────────────────────────────────────────────────────────────────────
 * Clean, consistent 16×16 / 20×20 SVG icons for the editor UI.
 * All icons use currentColor for easy color inheritance.
 * ─────────────────────────────────────────────────────────────────────────────
 */

interface IconProps {
    size?: number
    className?: string
    style?: React.CSSProperties
}

const I = ({ size = 16, className, style, children }: IconProps & { children: React.ReactNode }) => (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className} style={style}>
        {children}
    </svg>
)

